uint256 constant MAX_VAL = type(uint256).max;

// reverts on overflow
function safeAdd(uint256 x, uint256 y) pure returns (uint256) {
    return x + y;
}

// does not revert on overflow
function unsafeAdd(uint256 x, uint256 y) pure returns (uint256) { unchecked {
    return x + y;
}}

// does not revert on overflow
function unsafeSub(uint256 x, uint256 y) pure returns (uint256) { unchecked {
    return x - y;
}}

// does not revert on overflow
function unsafeMul(uint256 x, uint256 y) pure returns (uint256) { unchecked {
    return x * y;
}}

// does not overflow
function mulModMax(uint256 x, uint256 y) pure returns (uint256) { unchecked {
    return mulmod(x, y, MAX_VAL);
}}

// does not overflow
function mulMod(uint256 x, uint256 y, uint256 z) pure returns (uint256) { unchecked {
    return mulmod(x, y, z);
}}

contracts/ERC20AMM_Factory.sol.content:
// SPDX-License-Identifier: None

// Specifies the version of Solidity, using semantic versioning.
// Learn more: https://solidity.readthedocs.io/en/v0.5.10/layout-of-source-files.html#pragma
pragma solidity >=0.8.9;

/// @title Contract Factory for publishing new ERC20 Spec Tokens
/// @notice For use by Owners only
/// @author Aryan Rastogi

import "./ERC20_AMM.sol";
import "./Treasury.sol";

contract ERC20_Factory{

	address owner_addr;

	/// @notice Addresses of the deployed ERC20 (AMM) tokens.
	ERC20_AMM[] public erc20cts_AMM;

	/// @notice Addresses of the treasury contract.
	Treasury[] public treasury;

	/// @notice Event emitted when an ERC20 contract (AMM) is deployed.
	/// @param contract_addr: Address of the deployed contract.
	event Deployed_ERC20AMMto(address contract_addr);

	/// @notice Event emitted when a Treasury for ERC20 (AMM) is deployed.
	/// @param contract_addr: Address of the deployed contract.
	event Deployed_Treasuryto(address contract_addr);


	/// @notice Constructor to set owner of the contract.
	/// @param multisig_address: Address of the contract owner.
	constructor(address multisig_address) {
		owner_addr = multisig_address;
	}


	/// @notice Create new ERC20 AMM spec contracts using Bonding Curves. Accessible by the Owner.
	/// @param token_name: Name of the token.
	/// @param token_sym: Symbol of the token.
	/// @param founder_add: Address of the token founder.
	/// @param amt: Initial amount to mint.
	/// @param reserveRatio: The reserve ratio for the bonding curve.
	/// @param coll: Initial collateral staked by the founder
    /// @param proj_hash: Token URI of the project details
    /// @param stable_coin: Contract address of the stablecoin to be used as collateral.
	function createNewERC20AMM(string memory token_name, string memory token_sym, 
		address founder_add, uint256 amt, uint256 reserveRatio,
		uint256 coll, string memory proj_hash, address stable_coin) public {
		require(msg.sender == owner_addr, 'You should be the owner to create ERC20 tokens');
		Treasury tr = new Treasury(owner_addr, founder_add, coll, stable_coin);

		ERC20_AMM obj = new ERC20_AMM(token_name,token_sym,founder_add, owner_addr,
			amt, reserveRatio, address(tr), proj_hash);

		tr.setERC20Corr(address(obj));

		erc20cts_AMM.push(obj);

		treasury.push(tr);

		emit Deployed_ERC20AMMto(address(obj));
		emit Deployed_Treasuryto(address(tr));
	}


    /// @notice Get the address of the owner. Freely callable.
    /// @return Address of the owner.
    function getOwnerAddr() public view returns (address)
    {
        return owner_addr;
    }


}

contracts/Treasury.sol.content:
// SPDX-License-Identifier: None

// Specifies the version of Solidity, using semantic versioning.
// Learn more: https://solidity.readthedocs.io/en/v0.5.10/layout-of-source-files.html#pragma
pragma solidity >=0.8.9;

/// @title Treasury contract
/// @notice For use by ERC20 (AMM) contract
/// @author Aryan Rastogi


interface StableCoin {
    function transfer(address rec, uint amt) external returns (bool);
    function balanceOf(address acc) external view returns (uint);
    function transferFrom(address sen, address rec, uint256 amt) external returns (bool);
}

contract Treasury{

	event Withdraw(address to, uint256 amount);
	event Deposit(address from, uint256 amount);
	event TransferCollateralToFounder(uint256 amount);


	address owner;
	StableCoin coll_token;
	address founder;
	address factory;
	address erc20_address;

    /// @notice Initializes Treasury contract
    /// @param founder_addr: Address of the token founder
    /// @param owner_addr: Address of the owner
    /// @param stable_cn: Contract address of the stablecoin to be used as collateral
    /// @param ini_coll: Initial collateral staked by the founder
	constructor(address owner_addr, address founder_addr,
	 uint256 ini_coll, address stable_cn) {
		owner = owner_addr;
		founder = founder_addr;
		factory = msg.sender;
		coll_token = StableCoin(stable_cn);
		coll_token.transferFrom(founder_addr, address(this), ini_coll);
		emit Deposit(founder_addr, ini_coll);
	}

    /// @notice Deposits collateral to this contract's address
    /// @param sender: Address of the token sender
    /// @param amount: Amount to deposit to the contract
	function deposit(address sender, uint256 amount) external{
		require(msg.sender == erc20_address, "Only corresponding ERC20 can access" );
		require(coll_token.balanceOf(sender)>=amount, "Insufficient funds to perform a buy transaction");
		coll_token.transferFrom(sender, address(this), amount);
		emit Deposit(sender, amount);
	}

    /// @notice Withdraws collateral from this contract's address
    /// @param receiver: Address of the token receiver
    /// @param amount: Amount to withdraw from the contract
	function withdraw(address receiver, uint256 amount) external{
		require(msg.sender == erc20_address, "Only corresponding ERC20 can access" );
		require(coll_token.balanceOf(address(this))>=amount,
			"Treasury doesn't have sufficient tokens");
		coll_token.transfer(receiver, amount);
		emit Withdraw(receiver, amount);
	}

    /// @notice Transfers collateral held by this contract to the founder
    /// @param amount: Amount to transfer to the founder
	function transferToFounder(uint256 amount) external{
		require(msg.sender == erc20_address, "Only corresponding ERC20 can access" );
		coll_token.transfer(founder, amount);
		emit TransferCollateralToFounder(amount);
	}

    /// @notice Returns total collateral held by the account
    /// @return Total held value
	function getCollateralAmount() external view returns(uint256){
		return coll_token.balanceOf(address(this));
	}

    /// @notice Set the corresponding ERC20 contract address
	function setERC20Corr(address erc20_addr) external {
		require(msg.sender == factory, "Only factory can set this attribute");
		erc20_address = erc20_addr;
	}


}

